import django
from django.conf import settings
from django.db import connection

# Configure settings
if not settings.configured:
    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            '__main__',
        ],
        DEBUG=True,
    )
    django.setup()

from django.db import models

class ParentModel(models.Model):
    id = models.BigIntegerField(primary_key=True)

    class Meta:
        app_label = '__main__'

class ChildModel(ParentModel):
    pass

    class Meta:
        app_label = '__main__'

# Create tables
from django.db import connection
with connection.schema_editor() as schema_editor:
    schema_editor.create_model(ParentModel)
    schema_editor.create_model(ChildModel)

def test_force_insert():
    connection.queries_log.clear()

    # Given
    child = ChildModel(id=1)

    # When
    child.save(force_insert=True)

    # Then
    queries = [q['sql'] for q in connection.queries]
    print("Queries executed:")
    for i, q in enumerate(queries):
        print(f"{i}: {q}")

    # In SQLite, _do_update for a model with only PK will issue a SELECT EXISTS
    # We want to see if that SELECT is avoided when force_insert=True
    parent_table = '__main___parentmodel'
    update_attempt = any(f"SELECT 1 AS \"a\" FROM \"{parent_table}\" WHERE \"{parent_table}\".\"id\" = 1 LIMIT 1" in q for q in queries)

    if update_attempt:
        print("\nISSUE REPRODUCED: UPDATE (via SELECT EXISTS) attempted for parent model even with force_insert=True")
    else:
        print("\nISSUE NOT REPRODUCED: No UPDATE attempt found for parent model")

if __name__ == "__main__":
    test_force_insert()
