    id = models.BigIntegerField(primary_key=True)

    class Meta:
        app_label = '__main__'

class ChildModel(ParentModel):
    pass

    class Meta:
        app_label = '__main__'

# Create tables
from django.db import connection
with connection.schema_editor() as schema_editor:
    schema_editor.create_model(ParentModel)
    schema_editor.create_model(ChildModel)

def test_force_insert():
    connection.queries_log.clear()

    # Given
    child = ChildModel(id=1)

    # When
    child.save(force_insert=True)

    # Then
    queries = [q['sql'] for q in connection.queries]
    print("Queries executed:")
    for i, q in enumerate(queries):
        print(f"{i}: {q}")

    # Check for any query that looks like it's coming from _do_update on the parent table
    # For our ParentModel, _do_update will call .exists() because it only has a PK.
    # .exists() in SQLite results in a SELECT 1 ...
    parent_table = '__main___parentmodel'
    update_attempt = any(f"SELECT 1 AS \"a\" FROM {parent_table}" in q for q in queries)

    if update_attempt:
        print("\nISSUE REPRODUCED: Update attempt (SELECT for existence) found for parent model even with force_insert=True")
        return True
    else:
        print("\nISSUE NOT REPRODUCED: No update attempt found for parent model")
        return False

if __name__ == "__main__":
    if test_force_insert():
        exit(1)
    else:
        exit(0)
