from django.urls import path, resolve
from django.views import View
from pickle import dumps, loads
from importlib import import_module

# Configure Django settings
if not settings.configured:
    settings.configure(
        SECRET_KEY='test',
        ROOT_URLCONF=__name__,
    )
    django.setup()

def my_fbv(request):
    return HttpResponse('yay')

class MyView(View):
    def get(self, request):
        return HttpResponse('yay')

urlpatterns = [
    path('fbv/', my_fbv, name='my_fbv'),
    path('cbv/', MyView.as_view(), name='my_cbv'),
]

# Mock ResolverMatch with the fix
class ResolverMatchFixed:
    def __init__(self, func, args, kwargs, url_name=None, app_names=None, namespaces=None, route=None, tried=None):
        self.func = func
        self.args = args
        self.kwargs = kwargs
        self.url_name = url_name
        self.route = route
        self.tried = tried
        self.app_names = [x for x in app_names if x] if app_names else []
        self.app_name = ':'.join(self.app_names)
        self.namespaces = [x for x in namespaces if x] if namespaces else []
        self.namespace = ':'.join(self.namespaces)
        if not hasattr(func, '__name__'):
            self._func_path = func.__class__.__module__ + '.' + func.__class__.__name__
        else:
            self._func_path = func.__module__ + '.' + func.__name__
        view_path = url_name or self._func_path
        self.view_name = ':'.join(self.namespaces + [view_path])

    def __getstate__(self):
        state = self.__dict__.copy()
        func = state['func']
        if hasattr(func, 'view_class'):
            state['_func_reconstruct'] = ('cbv', func.view_class, func.view_initkwargs)
        elif hasattr(func, '__module__') and hasattr(func, '__name__'):
            state['_func_reconstruct'] = ('fbv', func.__module__, func.__name__)
        else:
            state['_func_reconstruct'] = ('unknown', None, None)
        del state['func']
        return state

    def __setstate__(self, state):
        reconstruct = state.pop('_func_reconstruct', None)
        if reconstruct:
            kind, *args = reconstruct
            if kind == 'cbv':
                view_class, initkwargs = args
                state['func'] = view_class.as_view(**initkwargs)
            elif kind == 'fbv':
                module_name, func_name = args
                try:
                    module = import_module(module_name)
                    state['func'] = getattr(module, func_name)
                except (ImportError, AttributeError):
                    state['func'] = None
            else:
                state['func'] = None
        self.__dict__.update(state)

def test_pickle_fbv():
    print("Testing FBV pickling...")
    try:
        match = ResolverMatchFixed(my_fbv, (), {}, url_name='my_fbv')
        pickled = dumps(match)
        unpickled = loads(pickled)
        print("FBV pickling successful!")
        assert unpickled.func == match.func
    except Exception as e:
        print(f"FBV pickling failed: {e}")
        raise e

def test_pickle_cbv():
    print("Testing CBV pickling...")
    try:
        cbv_func = MyView.as_view()
        match = ResolverMatchFixed(cbv_func, (), {}, url_name='my_cbv')
        pickled = dumps(match)
        unpickled = loads(pickled)
        print("CBV pickling successful!")
        assert unpickled.func == match.func
    except Exception as e:
        print(f"CBV pickling failed: {e}")
        raise e

if __name__ == "__main__":
    test_pickle_fbv()
    test_pickle_cbv()
