import os

# Add current directory to sys.path to import django
sys.path.append(os.path.abspath('/testbed'))

from django.db.models.base import Model
from django.conf import settings
import django

# Minimal settings for Django
if not settings.configured:
    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[],
    )
django.setup()

class MyModel(Model):
    class Meta:
        app_label = 'myapp'

class OtherModel(Model):
    class Meta:
        app_label = 'otherapp'

class MockAny:
    def __eq__(self, other):
        return True

class MockFalse:
    def __eq__(self, other):
        return False

def test_eq():
    model_instance = MyModel()

    print("Testing Model == MockAny (should be True):")
    any_instance = MockAny()
    result = (model_instance == any_instance)
    print(f"Result: {result}")
    assert result is True

    print("\nTesting Model == MockFalse (should be False):")
    false_instance = MockFalse()
    result = (model_instance == false_instance)
    print(f"Result: {result}")
    assert result is False

    print("\nTesting Model == OtherModel (should be False):")
    other_instance = OtherModel()
    result = (model_instance == other_instance)
    print(f"Result: {result}")
    assert result is False

    print("\nTesting Model == Model (same instance, should be True):")
    result = (model_instance == model_instance)
    print(f"Result: {result}")
    assert result is True

    print("\nAll tests passed!")

if __name__ == "__main__":
    try:
        test_eq()
    except AssertionError as e:
        print(f"Assertion failed!")
        sys.exit(1)
